// Cold-start cost model (ms) — edit these to test mitigations
const runtimeInit   = 120;  // container + language runtime boot
const classLoad     = 90;   // lazy module / class loading
const jitWarmup     = 260;   // JIT compiling hot paths on first calls
const poolConnect   = 140;   // connection pool establishing
const handlerWork   = 45;    // the actual steady-state request work

const BUDGET = 800; // p99 budget in ms

const coldFirst = runtimeInit + classLoad + jitWarmup + poolConnect + handlerWork;
const steady    = handlerWork; // warm: init already paid, JIT optimised, pool warm

console.log('cold first request:', coldFirst, 'ms');
console.log('steady-state request:', steady, 'ms');
console.log('cold overhead:', coldFirst - steady, 'ms');
console.log('fits 800ms p99 budget:', coldFirst <= BUDGET);
